node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Remove the cart item
db.prepare(\"DELETE FROM cart_items WHERE cart_item_id='CI-0012' AND customer_id='user_fbab7801'\").run();

// Update the cart: remove CI-0012 from item_ids_json, update subtotal and total
const newItemIds = JSON.stringify(['CI-0010', 'CI-0011']);
const newSubtotal = 79 - 16;  // 63
const shippingCost = 6;
const newTotal = newSubtotal + shippingCost;  // 69

db.prepare(\"UPDATE carts SET item_ids_json=?, subtotal=?, total=? WHERE cart_id='CART-user_fbab7801'\").run(newItemIds, newSubtotal, newTotal);

// Verify
const cart = db.prepare(\"SELECT * FROM carts WHERE customer_id='user_fbab7801'\").get();
const items = db.prepare(\"SELECT ci.*, p.name, p.price FROM cart_items ci JOIN products p ON ci.product_id=p.product_id WHERE ci.customer_id='user_fbab7801'\").all();
console.log('Updated cart:', JSON.stringify(cart, null, 2));
console.log('Remaining items:', JSON.stringify(items, null, 2));
"

